with filtered as (select *, round(budget * 1.07, 2) as adjusted_budget, trim(location) as clean_location, coalesce(location, 'UNKNOWN') as location_clean from departments where location in ('Singapore', 'London')), with_latest as (select s.*, x.employee_salary, x.level from filtered s left join lateral (select c.salary as employee_salary, c.level from employees c where c.dept_id = s.id order by c.salary desc, c.id desc limit 1) x on true), with_latest_departments as (select s.*, latest.employee_salary_2 from with_latest s join lateral (select c.salary as employee_salary_2 from employees c where c.dept_id = s.id order by c.hire_date desc, c.id desc limit 1) latest on true), enriched as (select *, ntile(3) over (order by employee_salary desc, id) as employee_salary_bucket, row_number() over (partition by level, location order by adjusted_budget desc, id) as row_seq, avg(employee_salary_2) over (partition by location order by adjusted_budget, id rows between 5 preceding and current row) as employee_salary_2_avg_5 from with_latest_departments) select dept_name, level, sort_array(collect_set(level)) as level_list, max(row_seq) filter (where level = 'L5') as l5_max_row_seq, sum(case when location = 'Chiang Mai' then employee_salary_bucket else 0 end) as chiang_mai_employee_salary_bucket from enriched group by dept_name, level order by l5_max_row_seq desc nulls first
